//! Differential vectors around the ported extension tests (`tests/vectors/upstream/extensions/differential.json`,
//! generated by `differential.gen.php` next to it): the APIs the PHPUnit tests exercise, with more inputs than their
//! assertions use.
//!
//! - `CoreExtension::compare()` (`twig::runtime::compare_values`) for every pair of a list of scalars and arrays;
//! - `EscaperRuntime::escape()` for values x strategies x charsets x autoescape;
//! - the binding of template arguments to host functions and filters with various PHP signatures (what the closure
//!   receives, or the compile error);
//! - the `CoreExtension` helpers of `CoreTest.php` through templates with edge inputs (output or exception, and
//!   deprecations).
//!
//! Regenerate the vectors (from the repository root; Git Bash on Windows needs MSYS_NO_PATHCONV=1):
//!
//!     MSYS_NO_PATHCONV=1 docker run --rm -i twig-oracle:3.31.1 php < tests/vectors/upstream/extensions/differential.gen.php > tests/vectors/upstream/extensions/differential.json

use std::sync::{Arc, LazyLock};

use twig::escaper::DefaultStrategy;
use twig::extension::runtime::{Call, CallResult, CallableRuntime, EscaperRuntime};
use twig::extension::{
    CallableParameter as P, FilterOptions, FunctionOptions, PhpCallable, TwigFilter, TwigFunction,
};
use twig::runtime::{DiagnosticsPolicy, Environment, EnvironmentOptions, Markup, compare_values};
use twig::value::object::{FunctionKind, ObjectRef, Param, StdClass};
use twig::value::{Array, ArrayKey, Ignore, PhpString, Throw, Value, convert};

use crate::classes::ExtensionTestClass;
use crate::common::{Json, base64_decode};
use crate::support::{deprecations, loader};

static VECTORS: LazyLock<Json> =
    LazyLock::new(|| Json::load_vectors("upstream/extensions/differential.json"));

/// The objects of the escape cases, by the ids of the generator.
fn objects() -> Vec<(&'static str, Value)> {
    let markup = |content: &str, strategies: Option<&[&str]>| {
        Value::Object(Markup::create(
            PhpString::from(content),
            Some(PhpString::from("UTF-8")),
            strategies.map(|s| s.iter().map(|s| PhpString::from(*s)).collect()),
        ))
    };
    vec![
        ("stringable", ExtensionTestClass::value()),
        ("plain", Value::Object(StdClass::new().into_ref())),
        ("markup", markup("<b>&amp;</b>", None)),
        ("markup_html", markup("<b>", Some(&["html"]))),
        ("markup_js", markup("<b>", Some(&["js"]))),
        ("markup_none", markup("<b>", Some(&[]))),
        ("markup_empty", markup("", None)),
    ]
}

/// Decodes a typed tree of the generator.
fn decode(json: &Json, objects: &[(&str, Value)]) -> Value {
    let field = |name: &str| json.field(name);
    match field("t").as_str() {
        Some("null") => Value::Null,
        Some("bool") => Value::Bool(field("v") == &Json::Bool(true)),
        Some("int") => Value::Int(field("v").as_str().unwrap().parse().unwrap()),
        Some("float") => Value::Float(f64::from_bits(
            u64::from_str_radix(field("v").as_str().unwrap(), 16).unwrap(),
        )),
        Some("string") => Value::from(base64_decode(field("b64").as_str().unwrap())),
        Some("array") => {
            let mut array = Array::new();
            for item in field("items").as_array() {
                let item = item.as_array();
                let key = match decode(&item[0], objects) {
                    Value::Int(i) => ArrayKey::Int(i),
                    Value::String(s) => ArrayKey::from(s),
                    other => panic!("bad key {other:?}"),
                };
                array.insert(key, decode(&item[1], objects));
            }
            Value::Array(array)
        }
        Some("object") => {
            let id = field("id").as_str().unwrap();
            objects
                .iter()
                .find(|(name, _)| *name == id)
                .map(|(_, value)| value.clone())
                .unwrap_or_else(|| panic!("unknown object {id}"))
        }
        other => panic!("bad typed tree {other:?}"),
    }
}

/// Whether a value is the one a typed tree describes (`===`; objects by identity or by class and string form).
fn matches(expected: &Json, actual: &Value, objects: &[(&str, Value)]) -> bool {
    if expected.field("t").as_str() == Some("object") {
        let Value::Object(object) = actual else {
            return false;
        };
        if let Some(id) = expected.get("id").and_then(Json::as_str) {
            return objects.iter().any(|(name, value)| {
                *name == id && matches!(value, Value::Object(o) if ObjectRef::ptr_eq(o, object))
            });
        }
        if object.class_name() != expected.field("class").as_str().unwrap_or_default() {
            return false;
        }
        return match expected.field("string") {
            Json::Null => true,
            string => object
                .to_php_string(&mut Ignore)
                .is_ok_and(|s| Value::String(s) == decode(string, objects)),
        };
    }
    twig::value::compare::identical(&decode(expected, objects), actual)
}

fn describe(value: &Value) -> String {
    crate::support::export(value)
}

#[test]
fn compare_matrix() {
    let compare = VECTORS.field("compare");
    let values: Vec<Value> = compare
        .field("values")
        .as_array()
        .iter()
        .map(|v| decode(v, &[]))
        .collect();
    let mut failures = Vec::new();
    for (i, row) in compare.field("results").as_array().iter().enumerate() {
        for (j, expected) in row.as_array().iter().enumerate() {
            let actual = compare_values(&values[i], &values[j], &mut Ignore);
            let ok = match (expected.as_i64(), &actual) {
                (Some(e), Ok(a)) => e == *a,
                _ => false,
            };
            if !ok {
                failures.push(format!(
                    "compare({}, {}): expected {expected:?}, got {:?}",
                    describe(&values[i]),
                    describe(&values[j]),
                    actual.map_err(|e| format!("{e:?}"))
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// `fn ($s, $c) => get_debug_type($s).':'.(is_scalar($s) || null === $s ? (string) $s : 'x').'@'.$c`.
fn custom_escaper() -> twig::extension::runtime::EscaperCallback {
    Arc::new(|value, charset, diag| {
        let scalar = match value {
            Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) | Value::String(_) => {
                convert::to_string(value, diag)?
            }
            _ => PhpString::from("x"),
        };
        Ok(Value::String(PhpString::concat(&[
            twig::value::types::get_debug_type(value).as_bytes(),
            b":",
            scalar.as_bytes(),
            b"@",
            charset.as_bytes(),
        ])))
    })
}

#[test]
fn escape_matrix() {
    let mut failures = Vec::new();
    let cases = VECTORS.field("escape").as_array();
    for case in cases {
        let objects = objects();
        let value = decode(case.field("value"), &objects);
        let strategy = case.field("strategy").as_str().unwrap();
        let charset = case.field("charset").as_str();
        let autoescape = case.field("autoescape") == &Json::Bool(true);
        let runtime = EscaperRuntime::default();
        runtime.set_escaper("foo", custom_escaper());
        let result = runtime.escape(
            value.clone(),
            strategy.as_bytes(),
            charset.map(str::as_bytes),
            autoescape,
            &mut Throw::error_exception(),
        );
        let label = format!(
            "escape({}, {strategy:?}, {charset:?}, {autoescape})",
            describe(&value)
        );
        match (case.get("result"), result) {
            (Some(expected), Ok(actual)) if matches(expected, &actual, &objects) => {}
            (None, Err(error)) => {
                let (class, message) = match error.twig_error() {
                    Some(e) => (e.class_name().to_owned(), e.to_string()),
                    None => {
                        let php = error.php_error().expect("a PHP throwable");
                        (
                            php.class().name().to_owned(),
                            php.message_lossy().into_owned(),
                        )
                    }
                };
                let expected_class = case.field("error").as_str().unwrap();
                let expected_message = case.field("message").as_lossy_string();
                if class != expected_class || message != expected_message {
                    failures.push(format!(
                        "{label}: expected {expected_class}: {expected_message}, got {class}: {message}"
                    ));
                }
            }
            (expected, actual) => failures.push(format!(
                "{label}: expected {expected:?} / {:?} {:?}, got {:?}",
                case.get("error"),
                case.get("message"),
                actual.map(|v| describe(&v)).map_err(|e| format!("{e:?}"))
            )),
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} mismatches:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}

/// The PHP signatures of the argument cases: (type, parameters, PHP parameters for named binding, is_variadic).
fn signature(id: &str) -> (&'static str, Vec<P>, Vec<Param>, bool) {
    let null = || twig::ast::ConstantValue::Null;
    let s = |v: &str| twig::ast::ConstantValue::from(v);
    let int = twig::ast::ConstantValue::Int;
    let empty = || twig::ast::ConstantValue::Array(Vec::new());
    match id {
        "abc" => (
            "function",
            vec![
                P::required("a"),
                P::optional("b", s("B")),
                P::optional("c", s("C")),
            ],
            vec![
                Param::required("a"),
                Param::optional("b", "B"),
                Param::optional("c", "C"),
            ],
            false,
        ),
        "rest" => (
            "function",
            vec![P::required("a"), P::variadic("rest")],
            vec![Param::required("a"), Param::variadic("rest")],
            false,
        ),
        "bucket" => (
            "function",
            vec![
                P::required("a"),
                P::optional("b", null()),
                P::optional("opts", empty()).array(),
            ],
            vec![
                Param::required("a"),
                Param::optional("b", Value::Null),
                Param::optional("opts", Value::Array(Array::new())),
            ],
            true,
        ),
        "names" => (
            "function",
            vec![P::required("someName"), P::optional("other_name", int(2))],
            vec![
                Param::required("someName"),
                Param::optional("other_name", 2),
            ],
            false,
        ),
        "variadic_rest" => (
            "function",
            vec![
                P::required("a"),
                P::optional("b", s("B")),
                P::variadic("rest"),
            ],
            vec![
                Param::required("a"),
                Param::optional("b", "B"),
                Param::variadic("rest"),
            ],
            true,
        ),
        "only_rest" => (
            "function",
            vec![P::variadic("values")],
            vec![Param::variadic("values")],
            false,
        ),
        "filter" => (
            "filter",
            vec![
                P::required("value"),
                P::optional("x", int(1)),
                P::optional("y", int(2)),
            ],
            vec![
                Param::required("value"),
                Param::optional("x", 1),
                Param::optional("y", 2),
            ],
            false,
        ),
        "filter_bucket" => (
            "filter",
            vec![
                P::required("value"),
                P::optional("x", int(1)),
                P::optional("more", empty()).array(),
            ],
            vec![
                Param::required("value"),
                Param::optional("x", 1),
                Param::optional("more", Value::Array(Array::new())),
            ],
            true,
        ),
        other => panic!("unknown signature {other}"),
    }
}

/// `json_encode(func_get_args())` of the closure: the positional arguments; named arguments (a spread of a mapping,
/// a variadic bucket) bound to a declared parameter extend them up to that parameter (skipped parameters take their
/// defaults), named arguments collected by a PHP variadic parameter are not part of `func_get_args()`. An `array`
/// parameter (`array $opts = []`, the bucket of `is_variadic` callables) rejects other values like PHP.
fn func_get_args(call: &mut Call<'_>, params: &[Param], array_param: Option<usize>) -> CallResult {
    if let Some(index) = array_param
        && let Some(value) = call.arg(index).cloned()
    {
        twig::value::param::verify_user_arg(
            value,
            &twig::value::param::DeclaredType::builtin(twig::value::param::TypeMask::ARRAY),
            &twig::value::param::UserArg::new("{closure}", index as u32 + 1, params[index].name),
            call.diagnostics(),
        )?;
    }
    let names: Vec<Vec<u8>> = call
        .named_args()
        .iter()
        .map(|(name, _)| name.as_bytes().to_vec())
        .collect();
    let last_named = params
        .iter()
        .rposition(|p| !p.variadic && names.iter().any(|n| n.as_slice() == p.name.as_bytes()))
        .map(|i| i + 1);
    // PHP binds named arguments first (`Unknown named parameter $x` without a variadic parameter)
    let bound = if names.is_empty() {
        None
    } else {
        Some(call.bind("{closure}", params, FunctionKind::User)?)
    };
    let args = match (last_named, bound) {
        (Some(last_named), Some(bound)) => {
            let count = call.args().len().max(last_named);
            bound.into_iter().take(count).collect()
        }
        _ => call.args().to_vec(),
    };
    Ok(twig::value::builtins::format::json_encode(
        &Value::Array(Array::from_values(args)),
        None,
        None,
        call.diagnostics(),
    )?)
}

#[test]
fn argument_binding() {
    let mut failures = Vec::new();
    let cases = VECTORS.field("arguments").as_array();
    for case in cases {
        let id = case.field("signature").as_str().unwrap();
        let template = case.field("template").as_str().unwrap();
        let (_kind, parameters, params, is_variadic) = signature(id);
        let array_param = parameters.iter().position(|p| p.array_type);
        let env = Environment::with_options(
            loader(&[("index", template)]),
            EnvironmentOptions {
                autoescape: DefaultStrategy::Disabled,
                diagnostics: DiagnosticsPolicy::Error,
                ..Default::default()
            },
        );
        // PHP registers the closure as a function and as a filter
        let callable = PhpCallable::closure(parameters);
        let params = Arc::new(params);
        CallableRuntime::new(move |call| func_get_args(call, &params, array_param))
            .attach(&callable);
        env.add_function(TwigFunction::new(
            "f",
            Some(callable.clone()),
            FunctionOptions {
                is_variadic,
                ..Default::default()
            },
        ))
        .unwrap();
        env.add_filter(TwigFilter::new(
            "f",
            Some(callable),
            FilterOptions {
                is_variadic,
                ..Default::default()
            },
        ))
        .unwrap();
        let result = env.render("index", Array::new());
        compare_render(
            case,
            &format!("{id} {template}"),
            &result,
            &deprecations(&env),
            &mut failures,
        );
    }
    assert!(
        failures.is_empty(),
        "{} of {} mismatches:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}

/// Compares a render with an oracle case: the output, or the exception class and message, and the deprecations.
fn compare_render(
    case: &Json,
    label: &str,
    result: &twig::Result<String>,
    deprecations: &[String],
    failures: &mut Vec<String>,
) {
    let expected_deprecations: Vec<String> = case
        .field("deprecations")
        .as_array()
        .iter()
        .map(Json::as_lossy_string)
        .collect();
    let expected_message = case
        .get("message")
        .map(Json::as_lossy_string)
        .unwrap_or_default();
    // PHP's TypeErrors of closures name them with their file and line (reference/deviations.md): the class and the
    // wrapping are compared
    let same_message = |message: &str| {
        message == expected_message
            || (expected_message.contains("{closure:")
                && message.split("{closure").next() == expected_message.split("{closure").next()
                && message.rsplit("\")").next() == expected_message.rsplit("\")").next())
    };
    match (case.get("output").and_then(Json::as_str), result) {
        (Some(expected), Ok(output)) if expected == output => {}
        (None, Err(error))
            if error.class_name() == case.field("error").as_str().unwrap_or_default()
                && same_message(&error.to_string()) => {}
        _ => failures.push(format!(
            "{label}: expected {:?}, got {:?}",
            case.get("output")
                .and_then(Json::as_str)
                .map(str::to_owned)
                .unwrap_or_else(|| format!(
                    "{}: {}",
                    case.field("error").as_str().unwrap_or_default(),
                    expected_message
                )),
            result
                .as_ref()
                .map_err(|e| format!("{}: {e}", e.class_name()))
        )),
    }
    if deprecations != expected_deprecations {
        failures.push(format!(
            "{label}: expected the deprecations {expected_deprecations:?}, got {deprecations:?}"
        ));
    }
}

#[test]
fn core_helper_templates() {
    let mut failures = Vec::new();
    let cases = VECTORS.field("templates").as_array();
    for case in cases {
        let template = case.field("template").as_str().unwrap();
        let env = Environment::with_options(
            loader(&[("index", template), ("x", "X"), ("empty", "")]),
            EnvironmentOptions {
                autoescape: DefaultStrategy::Disabled,
                diagnostics: DiagnosticsPolicy::Error,
                ..Default::default()
            },
        );
        twig::extension::runtime::mt_srand(1);
        let result = env.render("index", Array::new());
        compare_render(case, template, &result, &deprecations(&env), &mut failures);
    }
    assert!(
        failures.is_empty(),
        "{} of {} mismatches:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}
